namespace AsterHand {
    internal static partial class NativeTests {
        static Dictionary<string,object> Query(string url) {var u=new Uri(url);var result=J.Obj();foreach(string p in u.Query.TrimStart('?').Split('&')){var kv=p.Split(new[]{'='},2);result[Uri.UnescapeDataString(kv[0])]=Uri.UnescapeDataString(kv.Length>1?kv[1]:"");}return result;}
        static string Jwt(RSACryptoServiceProvider rsa,object claims) {string value=Wire.B64Url(Wire.Utf8(J.Write(J.Obj("alg","RS256","kid","fixture-rsa"))))+"."+Wire.B64Url(Wire.Utf8(J.Write(claims)));return value+"."+Wire.B64Url(rsa.SignData(Encoding.ASCII.GetBytes(value),CryptoConfig.MapNameToOID("SHA256")));}
        static async Task AuthTests() {
            using(var rsa=new RSACryptoServiceProvider(2048)) {
                var pub=rsa.ExportParameters(false);var keys=J.Obj("keys",new[]{J.Obj("kid","fixture-rsa","kty","RSA","n",Wire.B64Url(pub.Modulus),"e",Wire.B64Url(pub.Exponent))});
                var claim=J.Obj("iss","https://auth.openai.com","aud","oaiapp_fixture","sub","fixture-sub","email","fixture@example.invalid","nonce","fixture-nonce","exp",J.Now+3600);
                string token=Jwt(rsa,claim);
                Check(J.Str(ChatGPTAuth.VerifyIdentity(token,"oaiapp_fixture","fixture-nonce","https://auth.openai.com",keys,J.Now),"sub")=="fixture-sub","OIDC RS256 signature and identity validation");
                Reject(()=>ChatGPTAuth.VerifyIdentity(token,"wrong-client","fixture-nonce","https://auth.openai.com",keys,J.Now),"OIDC wrong audience rejected");
                Reject(()=>ChatGPTAuth.VerifyIdentity(token,"oaiapp_fixture","wrong-nonce","https://auth.openai.com",keys,J.Now),"OIDC wrong nonce rejected");
                Reject(()=>ChatGPTAuth.VerifyIdentity(token,"oaiapp_fixture","fixture-nonce","https://wrong.invalid",keys,J.Now),"OIDC wrong issuer rejected");
                Reject(()=>ChatGPTAuth.VerifyIdentity(token,"oaiapp_fixture","fixture-nonce","https://auth.openai.com",keys,J.Now+4000),"OIDC expired ID token rejected");
                string altered=token.Substring(0,token.LastIndexOf('.')+1)+Wire.B64Url(new byte[256]);Reject(()=>ChatGPTAuth.VerifyIdentity(altered,"oaiapp_fixture","fixture-nonce","https://auth.openai.com",keys,J.Now),"OIDC invalid signature rejected");
                using(var ec=new ECDsaCng(256)){ec.HashAlgorithm=CngAlgorithm.Sha256;byte[] b=ec.Key.Export(CngKeyBlobFormat.EccPublicBlob);var ecKeys=J.Obj("keys",new[]{J.Obj("kid","fixture-ec","kty","EC","crv","P-256","x",Wire.B64Url(b.Skip(8).Take(32).ToArray()),"y",Wire.B64Url(b.Skip(40).Take(32).ToArray()))});string unsigned=Wire.B64Url(Wire.Utf8(J.Write(J.Obj("alg","ES256","kid","fixture-ec"))))+"."+Wire.B64Url(Wire.Utf8(J.Write(claim)));string ecJwt=unsigned+"."+Wire.B64Url(ec.SignData(Encoding.ASCII.GetBytes(unsigned)));Check(J.Str(ChatGPTAuth.VerifyIdentity(ecJwt,"oaiapp_fixture","fixture-nonce","https://auth.openai.com",ecKeys,J.Now),"sub")=="fixture-sub","OIDC ES256 P-256 validation");}
                var vault=Create("oauth");using(var auth=new ChatGPTAuth(vault)) {
                    string url=auth.Begin(false);var query=Query(url);string host=J.Str(vault.State,"chatgptHostId"),redirect=J.Str(query,"redirect_uri"),state=J.Str(query,"state");
                    Check(J.Str(query,"client_id")=="dynamic_agent_client"&&J.Str(query,"agent_name_hint")=="AsterHand"&&J.Str(query,"code_challenge_method")=="S256","first sign-in registers real app name with PKCE");
                    var pendingState=J.Obj("redirect",redirect,"created",J.Now,"state",state,"client","dynamic_agent_client");string callback=redirect+"?state="+Uri.EscapeDataString(state)+"&code=fixture-code&client_id=oaiapp_fixture";
                    Reject(()=>ChatGPTAuth.ValidateCallback(callback+"&state=duplicate",pendingState),"duplicate OAuth callback parameters rejected");
                    Reject(()=>ChatGPTAuth.ValidateCallback(callback.Replace("127.0.0.1","127.0.0.2"),pendingState),"OAuth callback bound to exact loopback host");
                    Reject(()=>ChatGPTAuth.ValidateCallback(redirect+"?state=wrong&code=fixture-code&client_id=oaiapp_fixture",pendingState),"OAuth callback state mismatch rejected");
                    string nonce=J.Str(query,"nonce");bool exchanging=true,wrongNonce=false,slowExchange=false;int refreshCalls=0;
                    auth.Transport=(endpoint,body,form,ct)=>{if(endpoint.EndsWith("openid-configuration"))return Task.FromResult(J.Obj("issuer","https://auth.openai.com","jwks_uri","https://auth.openai.com/fixture-jwks","revocation_endpoint","https://auth.openai.com/fixture-revoke"));if(endpoint.EndsWith("fixture-jwks"))return Task.FromResult(keys);if(endpoint.EndsWith("fixture-revoke"))return Task.FromResult(J.Obj());if(J.Str(body,"grant_type")=="refresh_token"){refreshCalls++;return Task.FromResult(J.Obj("access_token","fixture-access-refreshed","refresh_token","fixture-refresh-rotated","expires_in",3600,"scope","chatgpt.tokens.use.direct"));}Check(J.Str(body,"client_id")=="oaiapp_fixture"&&J.Str(body,"redirect_uri")==redirect&&Wire.B64Url(Wire.Hash(Wire.Utf8(J.Str(body,"code_verifier"))))==J.Str(query,"code_challenge"),"code exchange preserves issued client, redirect and PKCE verifier");claim["nonce"]=wrongNonce?"invalid-fixture-nonce":nonce;claim["exp"]=J.Now+3600;var fixtureToken=exchanging?J.Obj("access_token","fixture-access","refresh_token","fixture-refresh","id_token",Jwt(rsa,claim),"expires_in",3600,"scope","openid chatgpt.tokens.use.direct"):J.Obj("id_token",Jwt(rsa,claim),"scope","openid");return slowExchange?Task.Delay(8500,ct).ContinueWith(_=>fixtureToken,ct):Task.FromResult(fixtureToken);};
                    await auth.Complete(callback,CancellationToken.None);Check(J.Str(auth.Selected,"email")=="fixture@example.invalid"&&auth.Profiles.Count==1,"validated ChatGPT profile saved");
                    Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(vault.DirectoryPath,"settings.dat"))).Contains("fixture-access"),"OAuth tokens protected by DPAPI");
                    string returning=auth.Begin(false);Check(J.Str(Query(returning),"client_id")=="oaiapp_fixture"&&J.Str(Query(returning),"ext_agent_host_id")==host,"returning sign-in reuses registration and stable host");Check(!Query(returning).ContainsKey("prompt"),"ordinary returning sign-in does not force new consent");query=Query(returning);redirect=J.Str(query,"redirect_uri");nonce=J.Str(query,"nonce");state=J.Str(query,"state");
                    using(var client=Net.Client(20)){var invalid=await client.GetAsync(redirect+"?state=wrong&code=fixture&client_id=oaiapp_fixture");Check((int)invalid.StatusCode==400,"loopback login listener rejects invalid callback");slowExchange=true;var slowWatch=System.Diagnostics.Stopwatch.StartNew();var valid=await client.GetAsync(redirect+"?state="+state+"&code=fixture&client_id=oaiapp_fixture");Check((int)valid.StatusCode==200&&J.Str(auth.Selected,"client_id")=="oaiapp_fixture","loopback login callback completes verified token exchange");Check(slowWatch.ElapsedMilliseconds>=8000,"slow token exchange does not expire the completed callback reply");slowExchange=false;}
                    auth.Cancel();
                    J.Map(auth.Selected)["expires_at"]=0;var refreshed=await auth.AccessToken(J.Str(auth.Selected,"id"),CancellationToken.None);Check(refreshed=="fixture-access-refreshed"&&J.Str(auth.Selected,"refresh_token")=="fixture-refresh-rotated"&&refreshCalls==1,"token refresh rotates credentials atomically");
                    query=Query(auth.Begin(true));redirect=J.Str(query,"redirect_uri");nonce=J.Str(query,"nonce");state=J.Str(query,"state");wrongNonce=true;await RejectAsync(()=>auth.Complete(redirect+"?state="+state+"&code=fixture-code&client_id=oaiapp_fixture",CancellationToken.None),"failed new sign-in identity validation rejected");Check(auth.Profiles.Count==1&&J.Str(auth.Selected,"access_token")=="fixture-access-refreshed","failed new login preserves original account");wrongNonce=false;
                    query=Query(auth.Begin(true));redirect=J.Str(query,"redirect_uri");nonce=J.Str(query,"nonce");state=J.Str(query,"state");exchanging=false;await auth.Complete(redirect+"?state="+state+"&code=fixture-code&client_id=oaiapp_fixture",CancellationToken.None);Check(auth.Profiles.Count==2&&J.Str(auth.Selected,"email")=="fixture@example.invalid"&&!ChatGPTAuth.PlanEnabled(auth.Selected),"identity-only sign-in retained without granting plan usage");await RejectAsync(()=>auth.AccessToken(J.Str(auth.Selected,"id"),CancellationToken.None),"identity-only profile cannot obtain an inference token");
                    var identityReload=new Vault(vault.DirectoryPath,null);Check(J.List(J.Get(identityReload.State,"chatgptProfiles")).Count==2,"identity-only account persists after reload");var consent=Query(auth.Begin(false,true,true));Check(J.Str(consent,"prompt")=="consent"&&J.Str(consent,"client_id")=="oaiapp_fixture","explicit plan enablement reuses issued client and requests consent");auth.Cancel();await RejectAsync(()=>auth.Complete(redirect+"?state="+state+"&code=fixture-code&client_id=oaiapp_fixture",CancellationToken.None),"cancelled sign-in cannot consume a callback");
                    await auth.SignOut(J.Str(auth.Selected,"id"),CancellationToken.None);Check(auth.Profiles.Count==1&&J.Str(auth.Selected,"access_token")=="fixture-access-refreshed","disconnecting identity-only account preserves original account");
                    await auth.SignOut(J.Str(auth.Selected,"id"),CancellationToken.None);Check(auth.Profiles.Count==0&&J.Str(vault.State,"chatgptHostId")==host,"sign out clears profile and preserves host ID");
                }
                var models=AiSettings.Models(J.Obj("models",new[]{J.Obj("slug","server-new-model","display_name","Current Model","visibility","list"),J.Obj("slug","hidden","visibility","hidden"),J.Obj("slug","another-model","visibility","list")}),true);
                Check(models.Count==2&&J.Str(models[0],"id")=="server-new-model"&&J.Str(models[0],"name")=="Current Model","live model catalog filters visibility and preserves server ordering");
                var old=Create("migration-ai");old.State["provider"]="deepseek";old.State["key"]="retained-key";old.State["model"]="retained-model";old.State["apiBase"]="https://api.deepseek.com";string identity=J.Write(J.Get(old.State,"identity"));AiSettings.Migrate(old);Check(J.Str(old.State,"provider")=="compatible"&&J.Str(AiSettings.Options(old),"key")=="retained-key"&&J.Write(J.Get(old.State,"identity"))==identity,"provider simplification preserves API configuration and device identity");
            }
            string complete="data: "+J.Write(J.Obj("type","response.output_text.delta","delta","你好"))+"\r\n\r\ndata: "+J.Write(J.Obj("type","response.completed","response",J.Obj("status","completed","output",new object[0])))+"\n\n";
            using(var stream=new MemoryStream(Wire.Utf8(complete))){string observed="";var response=await Agent.ReadSse(stream,CancellationToken.None,s=>observed=s);Check(J.Str(response,"status")=="completed"&&observed=="你好","ChatGPT SSE handles CRLF, Unicode and terminal completion");}
            using(var stream=new MemoryStream(Wire.Utf8("data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\n")))await RejectAsync(()=>Agent.ReadSse(stream,CancellationToken.None,null),"interrupted SSE is never successful inference");
            using(var stream=new MemoryStream(Wire.Utf8("data: {\"type\":\"response.failed\",\"response\":{\"error\":{\"code\":\"subscription_sharing_usage_limit_exceeded\"}}}\n\n")))await RejectAsync(()=>Agent.ReadSse(stream,CancellationToken.None,null),"ChatGPT streaming usage limit handled");
            Reject(()=>Net.Api("https://example.com/v1?key=secret","models"),"API URL query credentials rejected");
        }
